        for node in self.document.traverse(nodes.literal):
            if 'kbd' not in node.get('classes', []):
                continue

            text = node.astext()
            parts = []
            index = 0
            expect_key = True
            while index < len(text):
                if expect_key:
                    start = index
                    if text[index] in '-+^':
                        index += 1
                    else:
                        while index < len(text) and text[index] not in '-+^':
                            index += 1
                    parts.append(('key', text[start:index]))
                else:
                    parts.append(('separator', text[index]))
                    index += 1
                expect_key = not expect_key

            if sum(kind == 'key' for kind, value in parts) <= 1:
                continue

            node.clear()
            for kind, value in parts:
                if kind == 'key':
                    node += nodes.literal(value, value, classes=['kbd'])
                else:
                    node += nodes.Text(value)

    cls.run = run
    return cls


